namespace InkNote.Api.Modules.Notes.Domain;

/// <summary>
/// A Markdown note. State changes go through methods (Create/Update/MarkDeleted)
/// so the rules (version bump, timestamps) live in one place.
/// </summary>
public sealed class Note
{
    // EF Core needs a parameterless constructor; private keeps callers on Create().
    private Note() { }

    // Guid generated by the application (not by the database) so that, later, a client
    // can create a note while offline without risking an ID clash.
    public Guid Id { get; private set; }
    public string Title { get; private set; } = string.Empty;
    public string Content { get; private set; } = string.Empty;
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset UpdatedAt { get; private set; }

    // Incremented on every change; used for optimistic concurrency and, later, for sync.
    public int Version { get; private set; }

    // Soft delete: the row stays, it is only hidden from normal queries.
    public bool IsDeleted { get; private set; }

    public static Note Create(string title, string content, DateTimeOffset now) => new()
    {
        Id = Guid.CreateVersion7(), // time-ordered Guid: friendlier to database indexes
        Title = title,
        Content = content,
        CreatedAt = now,
        UpdatedAt = now,
        Version = 1,
    };

    public void Update(string title, string content, DateTimeOffset now)
    {
        Title = title;
        Content = content;
        UpdatedAt = now;
        Version++;
    }

    public void MarkDeleted(DateTimeOffset now)
    {
        IsDeleted = true;
        UpdatedAt = now;
        Version++;
    }
}
